{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Salicylic acid, an acidic ionizable molecule with high assay transfer, showed absolute bioavailability of 0.97 in humans after oral dosing, supporting high F for the acidic 4-hydroxycoumarin query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Ampicillin, a polar/acidic oral drug, had absolute bioavailability of 61.8% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Meperidine had systemic availability of 0.57 in normal subjects, well above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Bufuralol showed systemic availability of 0.77 in a healthy volunteer, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Tapentadol had absolute oral bioavailability of 32% in humans, above the 20% threshold, supporting high F despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Phenylbutyrate, an ionizable carboxylic acid, had absolute bioavailability of 78% in humans, supporting high F for an acidic molecule.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20% in humans, including acidic ionizable molecules; therefore phenprocoumon is predicted to have high oral bioavailability (F>=20%).",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for phenprocoumon were provided; inference relies on high-transfer analogues.",
    "The effect of acidic ionization on permeability is addressed only indirectly by salicylic acid and phenylbutyrate analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

